const $=x=>document.getElementById(x),defs={fear:[65,"恐懼之影"],locust:[95,"蝗災群"],calf:[160,"金牛之像"]},types={sheep:"群羊",food:"糧食",money:"金錢",grace:"恩典"},modes={grow:"耕耘",guard:"守望",burst:"收割"};let s,serial=0;function rand(){s.rng=(Math.imul(s.rng,1664525)+1013904223)>>>0;return s.rng/4294967296}function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(rand()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}function draw(){if(!s.deck.length){s.deck=shuffle(s.discard);s.discard=[]}return s.deck.shift()}function log(x){s.logs.unshift("回合"+s.turn+"："+x)}function init(){let id=$("enemyPick").value,b=$("bless").checked;serial++;s={id,max:defs[id][0],ehp:defs[id][0],maxHp:b?40:32,hp:b?40:32,shield:b?5:0,seed:b?2:0,herd:0,invest:0,guard:0,bleed:0,power:0,turn:1,mode:"grow",hand:[],deck:[],discard:[],chosen:[],swapped:false,struck:false,phase:"battle",rng:1001+serial*99,logs:[]};let all=[];for(let i=0;i<9;i++)for(let t of ["sheep","food","money"])all.push({id:t+i,t});for(let i=0;i<3;i++)all.push({id:"grace"+i,t:"grace"});s.deck=shuffle(all);for(let i=0;i<6;i++)s.hand.push(draw());log("遭遇"+defs[id][1]);render()}function intent(){let t=s.turn;if(s.id==="fear")return t%3===0?{name:"重擊",hits:[18]}:{name:"影爪",hits:[t%3===1?10:7]};if(s.id==="locust")return {name:"蟲群連擊",hits:Array(t%3===0?5:3).fill(t%3===0?5:4)};let phase=s.ehp<=56?3:s.ehp<=112?2:1,p=s.power;return {name:phase===3?"狂暴":phase===2?"踐踏":"衝撞",hits:phase===3?[13+p,8+p]:phase===2?[13+p]:[10+p],heal:t%4===0?8:0}}function count(){let n={sheep:0,food:0,money:0,grace:0};for(let i of s.chosen)n[s.hand[i].t]++;return n}function damage(x){let v=Math.min(s.ehp,Math.max(0,x));s.ehp-=v;return v}function heal(x){let v=Math.min(s.maxHp-s.hp,Math.max(0,x));s.hp+=v;return v}function finish(p){s.phase=p;log(p==="win"?"勝利":"戰敗");render()}function play(){if(s.phase!=="battle"||!s.chosen.length)return;let n=count(),a=n.sheep,b=n.food,c=n.money,g=n.grace,used=s.chosen.map(i=>s.hand[i]),reflect=1,half=false;if(s.mode==="grow"){let gain=(b+(b===3?1:0))*(g?2:1);s.seed+=gain;s.herd+=a;s.invest+=c;log("耕耘：播種+"+gain+" 牧養+"+a+" 投資+"+c)}else if(s.mode==="guard"){let sh=a*5+c*4+(a===3?6:0);s.shield+=sh;s.guard+=b;let h=heal(b*2);reflect+=c*.25;half=g>0;log("守望：護盾+"+sh+" 堅守+"+b+" 恢復"+h)}else{let usedSeed=Math.min(s.seed,b*2);s.seed-=usedSeed;let base=a*4+b*2+c*4+usedSeed*3,crit=c===3||rand()<c*.25,rage=s.hp/s.maxHp<=.3,raw=Math.ceil(base*(crit?(c===3?2:1.5):1)*(g?2:1)*(rage?1.25:1)),actual=damage(raw),h=heal(Math.min(5,Math.floor(actual*.15)));log("收割：傷害"+actual+(crit?" 爆擊":"")+(rage?" 瀕危增傷":"")+" 吸血"+h+" 引爆"+usedSeed)}let tick=s.seed*(2+s.herd)+s.invest;if(tick>0){let dealt=damage(tick);log("播種觸發，傷害"+dealt);if(s.mode==="grow")log("收成回饋恢復"+heal(s.seed>=10?3:s.seed>=5?2:1))}if(s.ehp<=0)return finish("win");let e=intent();for(let hit of e.hits){let d=half?Math.ceil(hit/2):hit;half=false;let block=Math.min(s.shield,d);s.shield-=block;s.hp=Math.max(0,s.hp-(d-block));if(block){let r=Math.ceil(block*reflect);damage(r);s.bleed+=s.guard;log("盾反"+r+" 流血+"+s.guard)}if(d>block)log("受到"+(d-block)+"傷害");if(s.hp<=0||s.ehp<=0)break}if(s.ehp<=0)return finish("win");if(s.hp<=0)return finish("lose");if(e.heal){s.ehp=Math.min(s.max,s.ehp+e.heal);log("敵人恢復"+e.heal)}if(s.bleed){log("流血傷害"+damage(s.bleed))}if(s.ehp<=0)return finish("win");if(s.id==="calf"&&s.turn%3===0){s.power=Math.min(8,s.power+2);log("金牛力量提升至+"+s.power)}s.discard.push(...used);s.hand=s.hand.filter((_,i)=>!s.chosen.includes(i));while(s.hand.length<6){let x=draw();if(!x)break;s.hand.push(x)}s.chosen=[];s.swapped=false;s.struck=false;s.turn++;render()}function strike(){if(s.mode!=="guard"||s.struck||!s.shield||s.phase!=="battle")return;let n=Math.min(8,s.shield);s.shield-=n;s.struck=true;log("盾轉攻造成"+damage(n));if(s.ehp<=0)finish("win");else render()}function swap(){if(s.swapped||s.chosen.length!==1)return;let i=s.chosen[0];s.discard.push(s.hand[i]);s.hand[i]=draw();s.chosen=[];s.swapped=true;render()}function render(){let e=intent(),n=count(),tri=s.mode==="grow"&&n.food===3||s.mode==="guard"&&n.sheep===3||s.mode==="burst"&&n.money===3;$("stats").textContent="理智 "+s.hp+"/"+s.maxHp+"｜"+defs[s.id][1]+" "+s.ehp+"/"+s.max+"｜第"+s.turn+"回合";$("effects").textContent="護盾"+s.shield+"｜播種"+s.seed+"｜牧養"+s.herd+"｜投資"+s.invest+"｜堅守"+s.guard+"｜流血"+s.bleed+"｜播種傷害"+(s.seed*(2+s.herd)+s.invest);$("intent").textContent="敵方預告："+e.name+" "+e.hits.join("+")+"傷害"+(e.heal?"，恢復"+e.heal:"");$("manuals").innerHTML=Object.entries(modes).map(([k,v])=>'<button data-mode="'+k+'" class="'+(s.mode===k?"on":"")+'">'+v+'</button>').join("");$("rules").textContent=s.mode==="grow"?"糧=播種+1，羊=牧養+1，錢=投資+1，恩典=新增播種翻倍。三糧額外播種+1。播種觸發時恢復1理智；播種5層恢復2、10層恢復3。":s.mode==="guard"?"羊=護盾+5，糧=恢復2理智及堅守+1，錢=護盾+4且當回合盾反倍率+25%，恩典=首次受擊減半。三羊額外護盾+6。可使用盾轉攻。":"羊=4傷害，糧=2傷害及引爆最多2層播種，錢=4傷害及爆擊率+25%，恩典=直接傷害翻倍。三錢必爆×2。直接攻擊實際扣血吸血15%（每回合最多5），理智≤30%直接增傷25%。";$("hand").innerHTML=s.hand.map((x,i)=>'<button class="card '+(s.chosen.includes(i)?"on":"")+'" data-i="'+i+'">'+types[x.t]+'</button>').join("");$("selection").textContent="已選"+s.chosen.length+"/3"+(tri?"｜專屬三連觸發！":"");$("swap").disabled=s.swapped||s.chosen.length!==1||s.phase!=="battle";$("strike").disabled=s.mode!=="guard"||s.struck||s.shield===0||s.phase!=="battle";$("end").disabled=!s.chosen.length||s.phase!=="battle";$("result").textContent=s.phase==="battle"?"戰鬥進行中｜未使用的牌保留，每回合補至6張":s.phase==="win"?"戰鬥勝利！":"戰敗，可重開測試";$("log").textContent=s.logs.join("\n")} $("manuals").onclick=e=>{let b=e.target.closest("[data-mode]");if(b&&s.phase==="battle"){s.mode=b.dataset.mode;render()}};$("hand").onclick=e=>{let b=e.target.closest("[data-i]");if(!b||s.phase!=="battle")return;let i=+b.dataset.i;if(s.chosen.includes(i))s.chosen=s.chosen.filter(x=>x!==i);else if(s.chosen.length<3)s.chosen.push(i);render()};$("reset").onclick=init;$("enemyPick").onchange=init;$("bless").onchange=init;$("end").onclick=play;$("strike").onclick=strike;$("swap").onclick=swap;init();